//! Provider-neutral runtime operations the Engine consumes.
//!
//! Nothing here names a wire protocol: ACP, Codex app-server, Claude SDK, Cursor and OpenCode
//! connectors each translate their own wire types at their edge (see [`crate::connectors`]).
//! A turn is split into *acceptance* (the connector took the work and, when the protocol allows,
//! names the native turn) and *terminal* (a later, single outcome). `stop` is only a request;
//! the writer is released by the terminal outcome, never by `stop` returning.

use std::future::Future;
use std::pin::Pin;

use async_trait::async_trait;

/// Terminal outcome of one turn. Variant names are persisted in `Event::TurnEnded.stop_reason`
/// (via `Debug`), so they must not be renamed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TurnStop {
    EndTurn,
    MaxTokens,
    MaxTurnRequests,
    Refusal,
    Cancelled,
    /// The provider reported a stop reason this build does not know. Not a retry signal.
    Unknown,
}

/// Neutral prompt content. Images are base64 data with a MIME type.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RuntimeBlock {
    Text(String),
    Image { data: String, mime_type: String },
}

/// Connector failure, already rendered for the user. After `send_turn` was accepted a failure
/// means the outcome is unknown; callers must not resend.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("{0}")]
pub struct RuntimeError(pub String);

/// Resolves exactly once with the turn's terminal outcome.
pub type TerminalFuture = Pin<Box<dyn Future<Output = Result<TurnStop, RuntimeError>> + Send>>;

/// Returned once the connector has taken the turn. `terminal` is the separate, later outcome.
pub struct TurnTicket {
    /// Provider's id for the turn when the protocol names one at acceptance.
    pub native_turn_id: Option<String>,
    pub terminal: TerminalFuture,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Support {
    Supported,
    Unsupported,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ResumeSupport {
    Unsupported,
    /// Re-attach without replaying history.
    Resume,
    /// Re-attach and replay history to the client.
    Load,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StopConfirmation {
    /// `stop` only sends the request; only the terminal outcome proves the turn ended.
    RequestOnly,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TurnAcceptance {
    /// The protocol has no separate acceptance reply: acceptance is the request being handed
    /// to the transport and `native_turn_id` stays `None`.
    Implicit,
    /// The protocol replies with a turn id before the terminal outcome.
    Acknowledged,
}

/// What a connector actually supports. Unlisted behavior is unsupported, never assumed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RuntimeCapabilities {
    pub resume: ResumeSupport,
    pub mcp_http: Support,
    pub mcp_sse: Support,
    pub stop: StopConfirmation,
    pub acceptance: TurnAcceptance,
}

#[async_trait]
pub trait ProviderRuntime: Send + Sync {
    fn capabilities(&self) -> RuntimeCapabilities;

    /// Hand one turn to the provider session. The returned future must not borrow `self`, so
    /// callers can await it without holding any engine lock.
    async fn send_turn(
        &self,
        session: &str,
        blocks: Vec<RuntimeBlock>,
    ) -> Result<TurnTicket, RuntimeError>;

    /// Request that the active turn stop. Does not wait; see [`StopConfirmation`].
    fn stop(&self, session: &str) -> Result<(), RuntimeError>;

    /// Tear down the provider process/connection without waiting for it to exit.
    fn dispose(&self);
}

