//! ACP adapter for [`ProviderRuntime`]. ACP wire types stop here.

use std::sync::Arc;

use async_trait::async_trait;

use crate::acp::wire::{AgentCaps, ContentBlock, StopReason};
use crate::acp::AcpClient;
use crate::provider_runtime::{
    ProviderRuntime, ResumeSupport, RuntimeBlock, RuntimeCapabilities, RuntimeError,
    StopConfirmation, Support, TurnAcceptance, TurnStop, TurnTicket,
};

pub struct AcpRuntime {
    client: Arc<AcpClient>,
    caps: AgentCaps,
}

impl AcpRuntime {
    pub fn new(client: Arc<AcpClient>, caps: AgentCaps) -> Self {
        Self { client, caps }
    }
}

fn support(advertised: bool) -> Support {
    if advertised {
        Support::Supported
    } else {
        Support::Unsupported
    }
}

fn block(block: RuntimeBlock) -> ContentBlock {
    match block {
        RuntimeBlock::Text(text) => ContentBlock::text(text),
        RuntimeBlock::Image { data, mime_type } => ContentBlock::Image { data, mime_type },
    }
}

fn stop(reason: StopReason) -> TurnStop {
    match reason {
        StopReason::EndTurn => TurnStop::EndTurn,
        StopReason::MaxTokens => TurnStop::MaxTokens,
        StopReason::MaxTurnRequests => TurnStop::MaxTurnRequests,
        StopReason::Refusal => TurnStop::Refusal,
        StopReason::Cancelled => TurnStop::Cancelled,
        StopReason::Unknown => TurnStop::Unknown,
    }
}

#[async_trait]
impl ProviderRuntime for AcpRuntime {
    fn capabilities(&self) -> RuntimeCapabilities {
        RuntimeCapabilities {
            // Matches the engine's order: native resume is preferred over load.
            resume: if self.caps.resume_session {
                ResumeSupport::Resume
            } else if self.caps.load_session {
                ResumeSupport::Load
            } else {
                ResumeSupport::Unsupported
            },
            mcp_http: support(self.caps.mcp_http),
            mcp_sse: support(self.caps.mcp_sse),
            stop: StopConfirmation::RequestOnly,
            acceptance: TurnAcceptance::Implicit,
        }
    }

    async fn send_turn(
        &self,
        session: &str,
        blocks: Vec<RuntimeBlock>,
    ) -> Result<TurnTicket, RuntimeError> {
        let client = self.client.clone();
        let session = session.to_string();
        let blocks: Vec<ContentBlock> = blocks.into_iter().map(block).collect();
        // `session/prompt` has no acceptance reply: the request is written when `terminal` is
        // first polled, and its response is the terminal outcome.
        Ok(TurnTicket {
            native_turn_id: None,
            terminal: Box::pin(async move {
                client
                    .prompt(&session, blocks)
                    .await
                    .map(stop)
                    .map_err(|error| RuntimeError(error.to_string()))
            }),
        })
    }

    fn stop(&self, session: &str) -> Result<(), RuntimeError> {
        self.client
            .cancel(session)
            .map_err(|error| RuntimeError(error.to_string()))
    }

    fn dispose(&self) {
        self.client.terminate();
    }
}

