// Writer guard: once the hierarchy exists, a writer which does not know the field (an older
// binary dropping it on read-modify-write) or which lowers its version is rejected by the
// database itself. Legacy documents (no `hierarchy`) are unaffected.
conn.execute_batch(
    "CREATE TRIGGER IF NOT EXISTS assistant_hierarchy_writer_guard BEFORE UPDATE ON assistant_state
     WHEN json_extract(OLD.body,'$.hierarchy') IS NOT NULL AND (
          json_extract(NEW.body,'$.hierarchy') IS NULL
       OR json_extract(NEW.body,'$.hierarchy.schema') IS NULL
       OR json_extract(NEW.body,'$.hierarchy.revision') < json_extract(OLD.body,'$.hierarchy.revision'))
     BEGIN SELECT RAISE(ABORT,'assistant hierarchy writer guard: save is missing hierarchy fields'); END;
     CREATE TRIGGER IF NOT EXISTS assistant_hierarchy_delete_guard BEFORE DELETE ON assistant_state
     WHEN json_extract(OLD.body,'$.hierarchy') IS NOT NULL
     BEGIN SELECT RAISE(ABORT,'assistant hierarchy writer guard: cannot delete hierarchy'); END;",
)?;

